selectedBodies.ingresso_redeem:
function ingresso_redeem(MMarketOperations.Operation[] memory operations, Actions.ActionArgs[] memory actions) external nonReentrant {
    if(!selfServiceAllowed){
      _checkOperator();
    }
    uint256 len = operations.length;
    address _operator = operator;
    require(len == actions.length, "operations and actions length mismatch");
    for (uint256 i = 0; i < len; i++) {
      if(msg.sender != _operator) {
        require(operations[i].user_1 == msg.sender, "only otoken owner can redeem");
      }
      require(operations[i].operationType == MMarketOperations.OperationType.Withdraw, "invalid operations array");
      require(actions[i].actionType == Actions.ActionType.Redeem, "invalid actions array");
      require(operations[i].asset_1 == actions[i].asset, "mmarket withdrawn asset is not redeemed otoken");
      require(operations[i].user_1 == actions[i].secondAddress, "redeem receiver must be otoken owner");
      require(operations[i].amount_1 == actions[i].amount, "redeem amount must be withdraw amount");
      require(operations[i].user_2 == address(this), "invalid withdraw recipient");
    }
    mmarket.operate(operations);
    controller.operate(actions);
  }

selectedBodies.ingresso_settle:
function ingresso_settle(Actions.ActionArgs[] memory actions) external nonReentrant {
    if(!selfServiceAllowed){
      _checkOperator();
    }
    uint256 len = actions.length;
    address _operator = operator;
    for (uint256 i = 0; i < len; i++ ){
      if(msg.sender != _operator) {
        require(actions[i].owner == msg.sender, "only vault owner can settle");
      }
      require(actions[i].actionType == Actions.ActionType.SettleVault, "invalid actions array");
      require(actions[i].secondAddress == actions[i].owner, "settle receiver must be vault owner");
    }
    controller.operate(actions);
  }
